// Extra questions for the "lower-sec-history" bank. Original questions written for this demo in the style of SEAB papers; not copied from real exams.
export default [
  // ---------------- Early Singapore (1299–1819) ----------------
  { topic: "Early Singapore (1299–1819)", skill: "understanding", difficulty: "easy", question: "Which text, written for the Malay court, tells the legend of Sang Nila Utama naming the island Singapura?", options: ["Nagarakretagama", "Sejarah Melayu (Malay Annals)", "Daoyi Zhilue", "The Treaty of London"], answer: 1, explanation: "The Sejarah Melayu (Malay Annals) is a Malay court text that tells the story of Sang Nila Utama from Palembang seeing a lion-like beast and naming the island Singapura.", whyWrong: ["The Nagarakretagama is a Javanese poem from the Majapahit court; it lists Tumasik but does not tell the Sang Nila Utama legend.", null, "The Daoyi Zhilue is the account of Chinese traveller Wang Dayuan, not a Malay court text.", "The Treaty of London (1824) was an Anglo-Dutch agreement, not a book of legends."] },
  { topic: "Early Singapore (1299–1819)", skill: "understanding", difficulty: "easy", question: "What does the name \"Singapura\" mean?", options: ["Sea Town", "Island of Gold", "Lion City", "Dragon's Teeth Gate"], answer: 2, explanation: "Singapura comes from the Sanskrit words \"singa\" (lion) and \"pura\" (city), so it means Lion City.", whyWrong: ["\"Sea Town\" is closer to the meaning often given for the older name Temasek, not Singapura.", "\"Island of Gold\" was a name linked to other parts of the region, not the meaning of Singapura.", null, "\"Dragon's Teeth Gate\" (Longyamen) was a Chinese name for a strait near Singapore, not the meaning of Singapura."] },
  { topic: "Early Singapore (1299–1819)", skill: "understanding", difficulty: "easy", question: "Who were the Orang Laut in early Singapore?", options: ["Sea people who lived on boats and served local rulers by guarding the waters", "British soldiers stationed at Fort Canning", "Chinese merchants who ran gambier plantations", "Portuguese sailors who attacked the port"], answer: 0, explanation: "The Orang Laut (\"sea people\") lived on boats and along the coasts, and helped Malay rulers by patrolling the seas and guiding ships.", whyWrong: [null, "The British only arrived in 1819; the Orang Laut were local sea people, not British troops.", "Gambier planters were Chinese settlers, a different group from the sea-dwelling Orang Laut.", "The Portuguese were European outsiders, not the local Orang Laut."] },
  { topic: "Early Singapore (1299–1819)", skill: "understanding", difficulty: "easy", question: "Why did many traders in the 14th century stay at ports like Temasek for several months?", options: ["They had to pay a tax for every week they stayed", "They were waiting for the monsoon winds to change direction before sailing on", "The port was closed to ships for half the year", "Their ships needed to be rebuilt after every voyage"], answer: 1, explanation: "Sailing ships depended on the monsoon winds. Traders often had to wait at ports until the winds changed so they could continue or return home.", whyWrong: ["Staying longer was due to the winds, not a weekly tax system.", null, "There is no evidence the port closed for half the year; ships waited because of the winds.", "Ships needed repairs at times, but the main reason for long stays was waiting for the monsoon."] },
  { topic: "Early Singapore (1299–1819)", skill: "understanding", difficulty: "easy", question: "Wang Dayuan visited the region in the 14th century and described a place called Danmaxi (Temasek). Who was he?", options: ["A Malay prince from Palembang", "A Portuguese ship captain", "A British East India Company officer", "A Chinese traveller who wrote about the places he visited"], answer: 3, explanation: "Wang Dayuan was a Chinese traveller whose account (Daoyi Zhilue) is one of the earliest written descriptions of Temasek.", whyWrong: ["The Malay prince from Palembang in the legend is Sang Nila Utama, not Wang Dayuan.", "The Portuguese only reached the region in the 1500s, long after Wang Dayuan's time.", "The British East India Company came to Singapore in 1819, centuries later.", null] },
  { topic: "Early Singapore (1299–1819)", skill: "application", difficulty: "medium", question: "In the 1600s, the Johor Sultanate placed a shahbandar (port officer) at the Singapore River. What does this BEST suggest about Singapore at that time?", options: ["Singapore was completely abandoned", "Singapore was a British trading post", "Singapore still had some value as a port within the Johor kingdom", "Singapore was the capital of the Majapahit empire"], answer: 2, explanation: "A port officer is only needed where ships come to trade, so a Johor shahbandar shows Singapore was still used as a port under Johor.", whyWrong: ["If it were abandoned, Johor would not need to station a port officer there.", "The British did not arrive until 1819, long after the 1600s.", null, "Majapahit was based in Java; by the 1600s Singapore was under Johor."] },
  { topic: "Early Singapore (1299–1819)", skill: "application", difficulty: "medium", question: "In 1819, Raffles recognised Tengku Hussein as Sultan of Johor before signing a treaty with him and the Temenggong. Why did Raffles do this?", options: ["Hussein had defeated the Dutch in battle", "A treaty signed with a recognised Sultan made the British claim to set up a post look lawful", "Hussein was the ruler chosen by the Dutch", "Hussein had asked Britain to make Singapore a colony"], answer: 1, explanation: "Hussein's younger brother had been backed as Sultan. By recognising Hussein, Raffles gained a Sultan who would sign the treaty, giving the British post a legal basis.", whyWrong: ["Hussein had not defeated the Dutch; this is invented.", null, "It was Hussein's younger brother who had Dutch-supported backing, not Hussein.", "Hussein agreed to a trading post in return for payments; he had not asked for a colony."] },
  { topic: "Early Singapore (1299–1819)", skill: "application", difficulty: "medium", question: "Archaeologists found many 14th-century everyday items, such as cooking pots and broken bowls, at Fort Canning and along the Singapore River. Which conclusion is BEST supported?", options: ["People lived and worked there, not just passed through", "Only foreign traders visited, and nobody lived there", "The British built a town there in the 1300s", "The settlement made no contact with other countries"], answer: 0, explanation: "Everyday household items in large numbers suggest a settled community living and working there.", whyWrong: [null, "Cooking pots and daily items point to people living there, not just visitors.", "The British arrived in 1819, not the 1300s.", "Other finds such as Chinese porcelain show contact with other countries, so this claim goes too far."] },
  { topic: "Early Singapore (1299–1819)", skill: "application", difficulty: "medium", question: "The Singapore Stone was a large rock with ancient writing on it, found at the mouth of the Singapore River. What does it suggest about early Singapore?", options: ["The British wrote it to mark their arrival", "It was a modern copy made for tourists", "It proves Singapore was empty before 1819", "People who could write lived or passed through Singapore long before 1819"], answer: 3, explanation: "The inscription was already there when the British arrived, showing an earlier society with a writing system had been in Singapore.", whyWrong: ["The writing was found by the British; it was not written by them.", "The stone was found in the 1800s; it was not a modern tourist copy.", "Ancient writing is evidence people WERE there before 1819, the opposite of this claim.", null] },
  { topic: "Early Singapore (1299–1819)", skill: "application", difficulty: "medium", question: "When the British arrived in 1819, they found Chinese planters growing gambier and pepper, and the Temenggong's followers living near the river. What does this show?", options: ["Singapore had no people before the British came", "Singapore already had a small population and some economic activity", "Singapore was already the busiest port in Asia", "Singapore was ruled by the Dutch in 1819"], answer: 1, explanation: "Planters and the Temenggong's community show Singapore was a small but inhabited place with farming and trade before 1819.", whyWrong: ["The planters and the Temenggong's followers show people WERE living there.", null, "A few plantations and a small settlement do not make it the busiest port in Asia.", "Singapore was part of Johor's lands, not a Dutch-ruled territory."] },
  { topic: "Early Singapore (1299–1819)", skill: "application", difficulty: "hard", question: "Historians say Singapore's history before 1819 shows cycles of rise and decline. Which set of events BEST supports this view?", options: ["Raffles arrived; the Straits Settlements formed; the Suez Canal opened", "Temasek grew only after the British arrived in 1819", "Temasek prospered in the 1300s; it declined around 1400; it revived as a Johor port; a settlement was burned by the Portuguese in the early 1600s", "Singapore stayed a busy port without a break from 1299 to 1819"], answer: 2, explanation: "This sequence shows growth, decline, revival and decline again, which is exactly a cycle of rise and fall.", whyWrong: ["These events are all after 1819 and show growth, not cycles before 1819.", "Temasek was already a trading port in the 1300s, long before the British.", null, "The port declined around 1400 and again in the 1600s, so it did not stay busy without a break."] },
  { topic: "Early Singapore (1299–1819)", skill: "application", difficulty: "hard", question: "A student claims: \"Singapore only became an important port because of the British.\" Which evidence BEST challenges this claim?", options: ["The British built a free port in 1819", "Raffles signed a treaty with local rulers", "Singapore's population grew quickly after 1819", "14th-century Chinese porcelain and coins found at Fort Canning, and Wang Dayuan's description of trade at Temasek"], answer: 3, explanation: "Archaeological finds and a written account from the 1300s show Temasek traded with the region about 500 years before the British arrived.", whyWrong: ["The free port supports the student's claim about British influence; it does not challenge it.", "The 1819 treaty is about the British arrival, so it does not show earlier importance.", "Growth after 1819 supports, rather than challenges, the student's claim.", null] },
  { topic: "Early Singapore (1299–1819)", skill: "application", difficulty: "hard", question: "Temasek was a small port lying between stronger powers in Java and Siam. Which explanation of its decline around 1400 is BEST supported by this situation?", options: ["Attacks or pressure from larger regional powers weakened it, and traders moved elsewhere", "It ran out of fresh water and was flooded by the sea", "The British closed its harbour", "Traders stopped using ships in the 1400s"], answer: 0, explanation: "A small port near powerful neighbours could be attacked or pressured. Accounts say its ruler fled around 1400, and trade then shifted to Melaka.", whyWrong: [null, "There is no strong evidence of a flood or water shortage; the situation points to regional power struggles.", "The British were not in the region around 1400.", "Sea trade by ship carried on and grew in the 1400s, for example at Melaka."] },
  { topic: "Early Singapore (1299–1819)", skill: "application", difficulty: "hard", question: "Which factor helps explain BOTH Temasek's success in the 1300s AND the British choice of Singapore in 1819?", options: ["Large rice fields on the island", "Its position on the sea route between China and India at the southern end of the Straits of Melaka", "A cool climate suited to Europeans", "Rich gold mines in the hills"], answer: 1, explanation: "In both periods Singapore's value came from its location on a key sea route, where ships passed and could stop to trade.", whyWrong: ["Singapore had little farmland; this was not the reason in either period.", null, "Singapore is hot and humid all year; climate did not attract either group.", "Singapore had no major gold mines; its value was its location."] },
  { topic: "Early Singapore (1299–1819)", skill: "application", difficulty: "hard", question: "A historian wants to check whether the Sejarah Melayu story of a 14th-century kingdom at Singapura is based on real events. Which evidence would be MOST useful?", options: ["A 2015 children's picture book retelling the legend", "A modern film about Sang Nila Utama", "Objects dated to the 14th century dug up at Fort Canning Hill", "A 1900s painting of a lion"], answer: 2, explanation: "Archaeological finds from the right time and place give independent evidence that can be checked against the written story.", whyWrong: ["A modern retelling is based on the same legend, so it cannot check whether it is true.", "A film is a modern creative work, not evidence from the 1300s.", null, "A 1900s painting was made centuries later and does not show a 14th-century kingdom existed."] },

  // ---------------- Colonial Singapore (1819–1942) ----------------
  { topic: "Colonial Singapore (1819–1942)", skill: "understanding", difficulty: "easy", question: "In 1867, the Straits Settlements became a Crown Colony. What did this change?", options: ["They were now ruled directly by the Colonial Office in London instead of from British India", "They became independent countries", "They were handed over to the Dutch", "They became part of the Johor Sultanate"], answer: 0, explanation: "Before 1867, the Straits Settlements were controlled from British India. As a Crown Colony they came directly under the Colonial Office in London.", whyWrong: [null, "Independence came much later; in 1867 they were still British colonies.", "The Dutch did not take over the Straits Settlements.", "The Straits Settlements stayed under British rule, not Johor's."] },
  { topic: "Colonial Singapore (1819–1942)", skill: "understanding", difficulty: "easy", question: "The Raffles Town Plan of 1822 divided the town into different areas. On what basis were most areas set out?", options: ["By the age of the residents", "By how rich each family was", "By religion only", "By ethnic group, such as a Chinese area and a Malay and Arab area at Kampong Glam"], answer: 3, explanation: "The Town Plan set aside separate areas (kampongs) for different ethnic communities, such as Chinatown and Kampong Glam.", whyWrong: ["Areas were not based on age.", "The plan grouped people mainly by ethnic community, not wealth.", "Religion overlapped with community, but the plan was mainly organised by ethnic group.", null] },
  { topic: "Colonial Singapore (1819–1942)", skill: "understanding", difficulty: "easy", question: "Who were the Samsui women?", options: ["British nurses at the General Hospital", "Women from southern China who came to Singapore to work, many at construction sites", "Malay women who ran the port", "Japanese women who arrived in 1942"], answer: 1, explanation: "Samsui women were migrant women from Sanshui in southern China, known for hard labour on building sites and their red headscarves.", whyWrong: ["They were Chinese migrant workers, not British nurses.", null, "They came from China, not from the Malay community.", "They came in the colonial period, before the Japanese Occupation."] },
  { topic: "Colonial Singapore (1819–1942)", skill: "understanding", difficulty: "easy", question: "Which was a common PUSH factor that made many Chinese leave southern China for Singapore in the 1800s?", options: ["Free housing promised by the British", "A cold climate in Singapore", "Poverty, floods and unrest in their home villages", "A law forcing everyone in China to emigrate"], answer: 2, explanation: "Push factors drive people away from home. Hardship such as poverty, natural disasters and unrest pushed many to seek work overseas.", whyWrong: ["Free housing would be a pull factor, and the British did not offer it.", "Singapore has a hot climate, and climate in the new place would be a pull, not a push factor.", null, "There was no law forcing everyone to leave China."] },
  { topic: "Colonial Singapore (1819–1942)", skill: "understanding", difficulty: "easy", question: "From the late 1800s, which two goods from Malaya passed through Singapore's port in large amounts?", options: ["Wheat and wool", "Tin and rubber", "Coffee and cotton", "Oil and gold"], answer: 1, explanation: "Tin and rubber from Malaya were shipped out through Singapore, making it a major port for these exports.", whyWrong: ["Wheat and wool were not major products of Malaya.", null, "Coffee and cotton were not Malaya's main exports in this period.", "Oil and gold were not the main goods passing through Singapore from Malaya at this time."] },
  { topic: "Colonial Singapore (1819–1942)", skill: "application", difficulty: "medium", question: "Many new Chinese migrants joined clan associations (huiguan) soon after arriving. Why?", options: ["They had to join by British law", "The associations collected taxes for the government", "The associations helped people from the same hometown or dialect group find jobs and lodging", "The associations trained migrants to become soldiers"], answer: 2, explanation: "Clan associations gave newcomers support, such as places to stay, job contacts and help in times of need, from people who shared their dialect or hometown.", whyWrong: ["Joining was voluntary; there was no British law forcing it.", "They were community self-help groups, not tax collectors.", null, "They provided welfare and contacts, not military training."] },
  { topic: "Colonial Singapore (1819–1942)", skill: "application", difficulty: "medium", question: "In the 1800s, a large share of the colonial government's income came from selling the right to sell opium. Why was it hard for the government to stop the opium trade?", options: ["As a free port, Singapore collected no import taxes, so opium money was a major source of revenue", "Opium was needed to build the harbour", "Most British officials used opium", "China ordered Singapore to keep selling opium"], answer: 0, explanation: "With no duties on trade, the government relied heavily on the opium revenue. Banning it would cut a large part of its income.", whyWrong: [null, "Opium was not a building material; the issue was government income.", "This is an unsupported claim; the main reason was revenue, not officials' habits.", "China did not order this; the decision was the colonial government's."] },
  { topic: "Colonial Singapore (1819–1942)", skill: "application", difficulty: "medium", question: "In the late 1800s, steamships began to replace sailing ships. How did this help Singapore's port?", options: ["Steamships needed no ports at all", "Steamships stopped at Singapore to refuel with coal and no longer had to wait for the monsoon winds", "Steamships could only sail to Penang", "Steamships made the Straits of Melaka less important"], answer: 1, explanation: "Steamships needed coal along the way, and Singapore became a coaling station. They could sail all year, so trade became more regular.", whyWrong: ["Steamships still needed ports for cargo and coal.", null, "Steamships called at many ports, and Singapore was a major one.", "The Straits became even busier as more steamships used them."] },
  { topic: "Colonial Singapore (1819–1942)", skill: "application", difficulty: "medium", question: "During the Great Depression of the 1930s, world prices of rubber and tin fell sharply. What was a likely result in Singapore?", options: ["More jobs were created at the docks", "Rubber prices rose in Singapore only", "The British gave everyone free rice", "Many workers lost their jobs, and the government limited the entry of new male migrants"], answer: 3, explanation: "With less trade, many lost their jobs. The government restricted immigration, for example through the Aliens Ordinance of 1933.", whyWrong: ["Falling trade meant fewer, not more, jobs at the docks.", "Prices fell worldwide; Singapore was not an exception.", "There was no free rice for everyone; many people suffered hardship.", null] },
  { topic: "Colonial Singapore (1819–1942)", skill: "understanding", difficulty: "medium", question: "The British completed a large naval base at Sembawang in 1938. What was its MAIN purpose?", options: ["To serve as a base for the British fleet to defend British interests in Asia", "To build ships for the Japanese navy", "To attract tourists to the north of Singapore", "To replace the commercial port at the Singapore River"], answer: 0, explanation: "The naval base was meant to let a British fleet protect Britain's colonies and trade routes in Asia.", whyWrong: [null, "It was a British base; Japan later became the enemy it was meant to guard against.", "It was a military base, not a tourist site.", "Trade continued at the commercial port; the base was for the navy."] },
  { topic: "Colonial Singapore (1819–1942)", skill: "application", difficulty: "hard", question: "By the early 1900s, many shophouses in Chinatown were badly overcrowded and disease spread easily. Which explanation is BEST?", options: ["The British banned building new houses", "Many migrants were sent back to China", "The population grew quickly through migration, but housing and sanitation did not keep pace", "Most people preferred to live in crowded rooms"], answer: 2, explanation: "Rapid migration brought many workers who needed cheap rooms near the port, while housing and sanitation were not planned for such numbers. The Singapore Improvement Trust was later set up in 1927 to tackle this.", whyWrong: ["There was no ban on building; the problem was that housing could not keep up.", "Sending migrants back would reduce, not cause, overcrowding.", null, "Workers crowded together because of low wages and few options, not because they preferred it."] },
  { topic: "Colonial Singapore (1819–1942)", skill: "application", difficulty: "hard", question: "In the 1800s, Chinese secret societies were powerful and sometimes fought on the streets. Why was it difficult for the British to control them?", options: ["The secret societies had a larger navy than the British", "There were few British officials, and most did not speak Chinese dialects, so they relied on community leaders", "The British wanted the riots to continue", "The secret societies were controlled from London"], answer: 1, explanation: "A small colonial staff that could not speak the dialects found it hard to understand or police the Chinese community directly. This later led to the Chinese Protectorate (1877).", whyWrong: ["Secret societies were land-based groups, not navies.", null, "Riots harmed trade, which the British wanted to protect.", "Secret societies were local groups, not run from London."] },
  { topic: "Colonial Singapore (1819–1942)", skill: "application", difficulty: "hard", question: "Singapore grew into a bigger port than Penang during the 1800s. Which reason BEST explains this?", options: ["Penang was ruled by the Dutch", "Singapore had more rubber estates than all of Malaya", "Singapore had a colder climate", "Singapore lay at the southern entrance of the Straits, on the main route to China and the islands of Southeast Asia"], answer: 3, explanation: "Ships to and from China and the eastern islands passed Singapore, so it was better placed than Penang to collect trade from many directions.", whyWrong: ["Penang was a British settlement and part of the Straits Settlements.", "Malaya's rubber estates were much larger than Singapore's; Singapore's strength was shipping.", "Both places are hot and tropical; climate was not the reason.", null] },
  { topic: "Colonial Singapore (1819–1942)", skill: "application", difficulty: "hard", question: "In the 1800s, Indian convicts were used to build roads and buildings such as St Andrew's Cathedral. What does this suggest about the colonial government's priorities?", options: ["It wanted to build what it needed for trade and government at low cost", "It wanted to give convicts high-paying jobs", "It had plenty of money and spent freely", "It wanted to train convicts as architects"], answer: 0, explanation: "Using convict labour kept building costs down while providing roads and public buildings that supported trade and administration.", whyWrong: [null, "Convicts were not paid high wages; that was why their labour was cheap.", "The government used convict labour precisely because it wanted to save money.", "Convicts did heavy labour, not architectural training."] },
  { topic: "Colonial Singapore (1819–1942)", skill: "application", difficulty: "hard", question: "A historian argues that colonial rule benefited wealthy merchants far more than ordinary workers. Which evidence BEST supports this?", options: ["Singapore's trade grew every decade", "The British built a naval base in 1938", "Trading firms made large profits while many coolies lived in crowded rooms and earned low wages", "The Straits Settlements became a Crown Colony"], answer: 2, explanation: "To show an unequal benefit, you need evidence about BOTH groups. This option contrasts merchants' profits with workers' poor conditions.", whyWrong: ["Growing trade shows the economy grew, but not who gained from it.", "A naval base is about defence, not about who benefited from colonial rule.", null, "A change in government does not show which groups gained more."] },

  // ---------------- Japanese Occupation and independence ----------------
  { topic: "Japanese Occupation and independence", skill: "understanding", difficulty: "easy", question: "On 8 December 1941, Japanese forces began their invasion of Malaya. Where did they first land?", options: ["Changi", "Kota Bharu", "Penang", "Johor Bahru"], answer: 1, explanation: "Japanese troops landed at Kota Bharu in northeast Malaya and then moved south towards Singapore.", whyWrong: ["Changi is in Singapore; the invasion began much further north in Malaya.", null, "Penang was captured later; it was not the first landing point.", "Johor Bahru was reached near the end of the campaign, just before the attack on Singapore."] },
  { topic: "Japanese Occupation and independence", skill: "understanding", difficulty: "easy", question: "During the Japanese Occupation, people called the Japanese currency \"banana money\". Why did it become almost worthless?", options: ["It was printed on banana leaves", "The British printed copies of it", "The Japanese printed huge amounts of it, so prices rose very sharply", "It could only be used to buy bananas"], answer: 2, explanation: "The notes had pictures of banana trees. Because so much was printed without control, its value collapsed and prices soared.", whyWrong: ["The name came from the banana tree picture on the notes, not the material.", "Its loss of value came from Japanese over-printing, not British copies.", null, "It could buy anything for sale; the name came from the picture on the notes."] },
  { topic: "Japanese Occupation and independence", skill: "understanding", difficulty: "easy", question: "What was the Kempeitai during the Japanese Occupation?", options: ["A local resistance group", "A Japanese school for children", "The Japanese military police, feared for arrests and torture", "A food distribution centre"], answer: 2, explanation: "The Kempeitai was the Japanese military police, which arrested, questioned and tortured people suspected of opposing Japan.", whyWrong: ["Resistance groups fought the Japanese; the Kempeitai hunted them.", "It was a police force, not a school.", null, "It was a feared security force, not a place for food."] },
  { topic: "Japanese Occupation and independence", skill: "understanding", difficulty: "easy", question: "On which date did Singapore become an independent and sovereign nation?", options: ["15 February 1942", "16 September 1963", "3 June 1959", "9 August 1965"], answer: 3, explanation: "Singapore separated from Malaysia and became an independent nation on 9 August 1965, now celebrated as National Day.", whyWrong: ["15 February 1942 was the British surrender to Japan.", "16 September 1963 was when Singapore joined Malaysia.", "1959 brought full internal self-government, not full independence.", null] },
  { topic: "Japanese Occupation and independence", skill: "understanding", difficulty: "easy", question: "After winning the 1959 general election, who became Singapore's first Prime Minister?", options: ["Lee Kuan Yew", "David Marshall", "Lim Yew Hock", "Tunku Abdul Rahman"], answer: 0, explanation: "The PAP won the 1959 election, and Lee Kuan Yew became the first Prime Minister of self-governing Singapore.", whyWrong: [null, "David Marshall was Chief Minister from 1955 to 1956, not Prime Minister in 1959.", "Lim Yew Hock was Chief Minister from 1956 to 1959, before the PAP won.", "Tunku Abdul Rahman was the Prime Minister of Malaya, not Singapore."] },
  { topic: "Japanese Occupation and independence", skill: "application", difficulty: "medium", question: "During the Occupation, the Japanese issued ration cards and urged people to grow tapioca and sweet potatoes. What problem were they responding to?", options: ["Too much rice in the markets", "Food shortages because wartime shipping and imports were cut off", "People refusing to eat rice", "A new law against farming"], answer: 1, explanation: "Singapore depended on imported rice. War cut imports, so food was rationed and people grew hardy crops to survive.", whyWrong: ["There was too little rice, not too much.", null, "People wanted rice but could not get enough of it.", "The Japanese encouraged farming; there was no law against it."] },
  { topic: "Japanese Occupation and independence", skill: "application", difficulty: "medium", question: "The British Military Administration (1945–1946) was nicknamed the \"Black Market Administration\". Why?", options: ["Its offices were painted black", "It was run by the Japanese", "Shortages, high prices and corruption continued, and black-market trading was widespread", "It banned all markets in Singapore"], answer: 2, explanation: "Right after the war, food and goods were still scarce. Black-market trade and corruption continued, and many people were disappointed with the returning British.", whyWrong: ["The nickname was about illegal trading, not paint colour.", "The Japanese had surrendered; the BMA was British.", null, "Markets were not banned; the problem was illegal trading at high prices."] },
  { topic: "Japanese Occupation and independence", skill: "understanding", difficulty: "medium", question: "Under the 1955 Rendel Constitution, which areas did the British STILL control?", options: ["Internal security, defence and foreign affairs", "Education and health", "Only the post office", "Nothing; Singapore became fully independent"], answer: 0, explanation: "The 1955 constitution gave elected local ministers some powers, but the British kept control of internal security, defence and foreign affairs.", whyWrong: [null, "Local ministers took charge of areas such as education and health.", "The British kept much more power than just the post office.", "Full independence only came in 1965."] },
  { topic: "Japanese Occupation and independence", skill: "application", difficulty: "medium", question: "In 1956, a Singapore team went to London to ask for full self-government, but the talks failed. What was the MAIN disagreement?", options: ["Which language to use in schools", "Who would control internal security", "Where to build the new airport", "Whether Singapore should join Indonesia"], answer: 1, explanation: "The British were unwilling to hand over control of internal security, as they feared communist influence. This was the key sticking point.", whyWrong: ["School language was a local issue, not the reason the London talks failed.", null, "An airport was not the issue in the constitutional talks.", "Joining Indonesia was never the proposal; the talks were about self-government."] },
  { topic: "Japanese Occupation and independence", skill: "application", difficulty: "medium", question: "In the 1962 referendum, Singapore voters were asked to choose between different options. What was the referendum about?", options: ["Whether to stay a British colony forever", "Who should be Prime Minister", "Whether to join Indonesia", "Which terms of merger with Malaya Singapore should accept"], answer: 3, explanation: "The referendum offered different forms (terms) of merger; there was no option to reject merger, which made it controversial.", whyWrong: ["Staying a colony was not one of the choices; the vote was about forms of merger.", "Prime Ministers are chosen through general elections, not this referendum.", "Joining Indonesia was not offered.", null] },
  { topic: "Japanese Occupation and independence", skill: "application", difficulty: "hard", question: "During the Occupation, the Japanese treated the Chinese community very harshly but tried to win Indian support. Which explanation BEST accounts for this?", options: ["Japan was at war with China, so it saw local Chinese as enemies, and it hoped Indians would help fight British rule in India", "The Chinese community was the smallest in Singapore", "The Indian community had invited Japan to invade", "Japan wanted to send all Indians back to India"], answer: 0, explanation: "Many local Chinese had supported China's war effort against Japan. Japan backed groups such as the Indian National Army, hoping to use Indian support against the British.", whyWrong: [null, "The Chinese were the largest community, and size was not the reason for the harsh treatment.", "There is no evidence the Indian community invited the invasion.", "Japan wanted to use Indian support against Britain, not send all Indians home."] },
  { topic: "Japanese Occupation and independence", skill: "application", difficulty: "hard", question: "Which statement BEST explains the political disagreement between the PAP and the central Malaysian government after merger?", options: ["Both sides agreed fully on how races should be treated", "The PAP called for a \"Malaysian Malaysia\" with equal treatment for all races, which clashed with the central government's approach", "The central government wanted Singapore to become a British colony again", "The PAP wanted Malaysia to join Indonesia"], answer: 1, explanation: "The PAP's call for a \"Malaysian Malaysia\" was seen by some Malaysian leaders as challenging the special position of the Malays, causing serious political tension.", whyWrong: ["If they fully agreed, there would have been no disagreement to explain.", null, "Neither side wanted a return to colonial rule.", "Indonesia opposed Malaysia (Konfrontasi); the PAP did not want to join Indonesia."] },
  { topic: "Japanese Occupation and independence", skill: "application", difficulty: "hard", question: "Singapore hoped merger would give it a larger market for its goods. Why did economic relations with the central government become tense?", options: ["Singapore refused to trade with Malaysia at all", "Malaysia closed Singapore's port", "The common market was set up more slowly than Singapore hoped, and the two sides argued over how much revenue Singapore should give", "Singapore wanted to change its currency to the yen"], answer: 2, explanation: "Disputes over the slow progress of the common market and Singapore's share of revenue to the central government added to the tensions that led to separation.", whyWrong: ["Singapore wanted MORE trade with Malaysia, which was the point of a common market.", "The port was not closed; the dispute was over the common market and revenue.", null, "The yen was the Japanese currency; this was never proposed."] },
  { topic: "Japanese Occupation and independence", skill: "application", difficulty: "hard", question: "Which combination of factors BEST explains why Singapore separated from Malaysia in 1965?", options: ["The Japanese Occupation, the BMA and the 1955 elections", "British pressure to leave, the end of Konfrontasi and a water shortage", "Singapore's wish to rejoin Johor, and a failed referendum", "Political differences, economic disagreements and the 1964 racial riots"], answer: 3, explanation: "Political disputes, quarrels over the common market and revenue, and racial tension shown in the 1964 riots together led to separation.", whyWrong: ["These events all happened well before merger in 1963, so they cannot explain separation in 1965.", "Konfrontasi only ended in 1966, after separation, and was not a cause of it.", "Singapore did not seek to rejoin Johor, and the 1962 referendum was not a failure.", null] },
  { topic: "Japanese Occupation and independence", skill: "application", difficulty: "hard", question: "In the Battle of Singapore, the British side had more soldiers than the Japanese, yet surrendered. Which factor BEST explains the defeat?", options: ["The Japanese had more troops on the island", "The Japanese had control of the air and sea after British warships were sunk, and their troops moved quickly and were well prepared", "The British had too many aircraft to manage", "The local population refused to let the British fight"], answer: 1, explanation: "With the warships Prince of Wales and Repulse sunk and few aircraft, the British could not stop fast-moving, experienced Japanese troops, even with more soldiers.", whyWrong: ["The question states the British had more soldiers, so this contradicts the facts.", null, "The British had too FEW aircraft, which left them weak in the air.", "Local people did not stop the British from fighting; some, such as the Malay Regiment, fought bravely."] },

  // ---------------- Source-based questions ----------------
  { topic: "Source-based questions", skill: "understanding", difficulty: "easy", question: "Which of these is a SECONDARY source about the Japanese Occupation of Singapore?", options: ["A ration card issued in 1943", "A diary written by a nurse in 1942", "A textbook chapter written in 2010 about the Occupation", "A photograph taken on 15 February 1942"], answer: 2, explanation: "A secondary source is created later by someone who was not there, using other sources. A 2010 textbook fits this.", whyWrong: ["A 1943 ration card comes from the time itself, so it is a primary source.", "A diary written during the event is a primary source.", null, "A photograph taken at the time is a primary source."] },
  { topic: "Source-based questions", skill: "application", difficulty: "easy", question: "Source A (practice source, a hawker's diary, 1943): \"Rice now costs ten times what it did before the war. My children eat tapioca three times a day.\" What can you infer from Source A?", options: ["Food was cheap during the Occupation", "Rice was very expensive and scarce, so people ate substitutes", "The hawker's children preferred tapioca to rice", "The war had not yet started in 1943"], answer: 1, explanation: "Rice costing ten times more and eating tapioca daily suggests rice was scarce and costly, so families relied on substitutes.", whyWrong: ["The diary says prices rose ten times, so food was not cheap.", null, "Eating tapioca three times a day suggests necessity, not preference.", "The diary refers to \"before the war\", showing the war was already happening."] },
  { topic: "Source-based questions", skill: "understanding", difficulty: "easy", question: "When historians look at the \"provenance\" of a source, what are they checking?", options: ["How long the source is", "Whether the source has pictures", "How many copies of the source exist", "Who made the source, when, and for what purpose"], answer: 3, explanation: "Provenance means the origin of a source: its author, date and purpose. This helps judge reliability.", whyWrong: ["Length tells you little about where a source came from.", "Pictures are part of content, not provenance.", "The number of copies does not tell you who made it or why.", null] },
  { topic: "Source-based questions", skill: "application", difficulty: "easy", question: "Source B (practice source, a description of a 1900 photograph): \"Bullock carts and rickshaws crowd the riverbank at Boat Quay, beside dozens of small cargo boats.\" What does Source B suggest about the Singapore River in 1900?", options: ["It was a busy area for moving goods and trade", "It was a quiet place with few people", "It was used mainly for swimming", "It had no boats"], answer: 0, explanation: "Many carts, rickshaws and cargo boats suggest goods were being moved and traded there, so it was a busy trading area.", whyWrong: [null, "Crowded carts and boats show it was busy, not quiet.", "The source shows cargo boats and carts, not swimmers.", "The source clearly mentions dozens of boats."] },
  { topic: "Source-based questions", skill: "understanding", difficulty: "easy", question: "A student wants to test whether a source is RELIABLE. Which question is MOST helpful?", options: ["Is the source written neatly?", "Did the author have a reason to exaggerate or hide anything?", "Is the source in colour?", "Is the source very old?"], answer: 1, explanation: "Reliability depends on whether the author could be biased or had a purpose that might shape what they said.", whyWrong: ["Neat writing says nothing about whether the content is true.", null, "Colour has nothing to do with accuracy.", "Being old does not make a source reliable or unreliable on its own."] },
  { topic: "Source-based questions", skill: "application", difficulty: "medium", question: "Source C (practice source, a 1930s poster): \"Join the Volunteer Force! Defend your home and your family!\" What was the MAIN purpose of Source C?", options: ["To report the news of a battle", "To sell household goods", "To persuade local men to sign up to help defend Singapore", "To warn people to leave Singapore"], answer: 2, explanation: "Recruitment posters use appeals such as protecting home and family to persuade people to join.", whyWrong: ["It gives no news; it urges people to act.", "Nothing in the poster is for sale.", null, "It asks people to defend their home, not leave it."] },
  { topic: "Source-based questions", skill: "application", difficulty: "medium", question: "Source D (practice source, a wartime newspaper under Japanese control, 1942): \"The screening of residents was quick and orderly.\" Source E (practice source, a survivor's account): \"Hundreds of men were taken away in lorries and never returned.\" How do the sources DIFFER?", options: ["Both say the screening was harmless", "Both say many men disappeared", "Source D says it was orderly, while Source E shows it was brutal and deadly", "Source E praises the Japanese"], answer: 2, explanation: "Source D presents the screening as calm and orderly; Source E describes men taken away and never returning, showing brutality.", whyWrong: ["Source E clearly does not say the screening was harmless.", "Source D does not mention anyone disappearing.", null, "Source E describes suffering; it does not praise the Japanese."] },
  { topic: "Source-based questions", skill: "application", difficulty: "medium", question: "Source F (practice source, a description of a 1965 cartoon): A small boat marked \"Singapore\" sails away from a large ship, towards dark storm clouds, as its captain looks worried. What is the MESSAGE of Source F?", options: ["Singapore faced an uncertain and difficult future after separation", "Singapore was joining a larger navy", "Singapore's future was completely safe", "Singapore was being attacked by pirates"], answer: 0, explanation: "The small boat leaving the big ship represents Singapore leaving Malaysia; the storm and worried captain show uncertainty ahead.", whyWrong: [null, "The boat is sailing AWAY from the big ship, not joining it.", "Storm clouds and a worried captain suggest danger, not safety.", "There are no pirates; the storm is a symbol of challenges ahead."] },
  { topic: "Source-based questions", skill: "application", difficulty: "medium", question: "Source G (practice source, a 1950 housing report): \"In one shophouse we found 11 families sharing a single kitchen and toilet.\" Source G would be MOST useful for studying which topic?", options: ["The Japanese invasion of Malaya", "Overcrowded living conditions in post-war Singapore", "Trade at Temasek in the 1300s", "The opening of the Suez Canal"], answer: 1, explanation: "The report gives direct details about crowded housing in 1950, making it useful for studying post-war living conditions.", whyWrong: ["The invasion was in 1941–1942; this report is about housing in 1950.", null, "The source is from 1950, not the 1300s.", "The Suez Canal opened in 1869 and is unrelated to this housing report."] },
  { topic: "Source-based questions", skill: "application", difficulty: "medium", question: "Source H (practice source) is a memoir written in 1990 by a former prisoner of war, describing Changi in 1943. How could a historian BEST check its accuracy?", options: ["Assume it is true because the writer was there", "Reject it because it was written in 1990", "Count the number of pages in the memoir", "Cross-check it with other sources from the time, such as camp records or other prisoners' diaries"], answer: 3, explanation: "Cross-referencing with other evidence helps confirm details, since memories written many years later may be incomplete.", whyWrong: ["Being there helps, but memories can fade or be shaped later, so it should still be checked.", "A late memoir can still be useful; it should be checked, not thrown away.", "The length of a memoir does not show whether it is accurate.", null] },
  { topic: "Source-based questions", skill: "application", difficulty: "hard", question: "Source I (practice source, an 1880s report by a British official in charge of protecting migrant workers): \"Our department has ended the abuse of coolies entirely.\" Which is the BEST evaluation of its reliability?", options: ["Fully reliable, because officials always report the truth", "Not fully reliable, because the official had a reason to praise his own department, and \"entirely\" is an exaggerated claim to check against other evidence", "Unreliable, because it was written in the 1880s", "Fully reliable, because it is a government document"], answer: 1, explanation: "The author's purpose (making his department look successful) and the sweeping word \"entirely\" mean the claim needs cross-checking.", whyWrong: ["Officials can be biased, especially about their own work.", null, "Age alone does not make a source unreliable.", "Government documents can still be one-sided; type alone does not prove reliability."] },
  { topic: "Source-based questions", skill: "application", difficulty: "hard", question: "Source J (practice source, a shopkeeper's letter, late 1964): \"Since the riots, I close my shop early. I worry for my neighbours' safety too.\" Are you surprised by Source J?", options: ["Yes, because there was no unrest in Singapore in 1964", "Yes, because shopkeepers were never affected by events", "No, because the 1964 racial riots and curfews made many people fearful for their safety", "No, because the Japanese had just invaded Singapore"], answer: 2, explanation: "The 1964 racial riots led to deaths, curfews and fear. A shopkeeper closing early out of worry fits what we know about the time.", whyWrong: ["There were serious racial riots in 1964, so this is factually wrong.", "Shopkeepers were directly affected by curfews and violence.", null, "The Japanese invasion was in 1942, not 1964."] },
  { topic: "Source-based questions", skill: "application", difficulty: "hard", question: "Source K (practice source, a 1938 newspaper article): \"With the new naval base, Singapore cannot be captured.\" How should a historian BEST use Source K?", options: ["As evidence that British defences were strong enough in 1942", "As proof the Japanese never reached Singapore", "As useless, because the claim turned out to be false", "As evidence of how confident people were about Singapore's defences before the war"], answer: 3, explanation: "Even a wrong prediction is useful: it shows the attitudes and confidence of the time, which helps explain the shock of the 1942 surrender.", whyWrong: ["Singapore fell in 1942, so the source cannot prove the defences were strong enough.", "The Japanese did capture Singapore in 1942.", "A false claim can still show what people believed at the time.", null] },
  { topic: "Source-based questions", skill: "application", difficulty: "hard", question: "Source L (practice source, a 1962 leaflet by a group supporting merger): \"Merger means more jobs, bigger markets and a brighter future!\" What is the BEST explanation of its purpose?", options: ["To persuade voters to support merger by appealing to economic benefits", "To report the result of the 1962 referendum", "To argue that Singapore should stay a British colony", "To warn people that merger would cause unemployment"], answer: 0, explanation: "The leaflet stresses jobs and markets to win voters over to merger; that is its purpose, not just its content.", whyWrong: [null, "It was written to influence voters, not to report a result.", "It supports merger, not continued colonial rule.", "It claims merger brings MORE jobs, the opposite of warning about unemployment."] },
  { topic: "Source-based questions", skill: "application", difficulty: "hard", question: "Source M (practice source, a migrant's letter, 1890): \"Dock work is hard and the pay is small, but I earn more than in my village in China.\" Source N (practice source, a British report, 1890): \"Coolies earn more than they could in China, yet live in crowded lodgings.\" On which point do they AGREE?", options: ["Workers lived in spacious homes", "Workers earned more in Singapore than they could in China", "Dock work was easy", "The British paid all workers high wages"], answer: 1, explanation: "Both sources say migrants earned more than they would have in China, so that is the point of agreement.", whyWrong: ["Source N says lodgings were crowded, and Source M does not mention housing.", null, "Source M says the work was hard, and Source N does not say it was easy.", "Source M says the pay was small; neither source says wages were high."] },
];
